import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'expression' or feats.types[i] == 'copy_number':
            # Use Welch's t-test p-value
            t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)[1]
            if t_stat < 0.05:
                sig_features.append((fid, t_stat))

    # Sort by significance
    sig_features.sort(key=lambda x: x[1])

    # Remove near-duplicates (correlated with |r| >= 0.6)
    to_remove = set()
    corr_pairs = [
        ('IXTU9', 'NEDZ18'), ('BKMF9', 'DGX5B'), ('NDL15', 'RSS12'), ('NDL15', 'VOOB1P'),
        ('BKMF9', 'NDL15'), ('ADU4', 'TMQN5'), ('NDL15', 'IIIG17B'), ('ADU4', 'FJZ17'),
        ('DYV9', 'OTC8'), ('NDL15', 'GIWM4'), ('RQE4P', 'DDHC16'), ('PBU6L', 'NDL15'),
        ('RSS12', 'VOOB1P'), ('NDL15', 'VNFB8P'), ('RSS12', 'VNFB8P'), ('VOOB1P', 'XOU17P'),
        ('GDW18', 'BLQ4'), ('RSS12', 'IIIG17B'), ('ERV12', 'XOU17P'), ('PBU6L', 'RSS12')
    ]

    for a, b in corr_pairs:
        if a in feats.ids and b in feats.ids:
            col_a = feats.column(a)
            col_b = feats.column(b)
            r = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]
            if abs(r) >= 0.6:
                # Prefer the more significant one
                idx_a = -1
                idx_b = -1
                for j, (fid, _) in enumerate(sig_features):
                    if fid == a:
                        idx_a = j
                    elif fid == b:
                        idx_b = j
                if idx_a != -1 and idx_b != -1:
                    if sig_features[idx_a][1] < sig_features[idx_b][1]:
                        to_remove.add(b)
                    else:
                        to_remove.add(a)

    # Select top features, excluding near-duplicates
    selected = [fid for fid, _ in sig_features if fid not in to_remove][:MAX_DRIVERS]

    # If no significant features, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For simplicity, we'll just use the most significant ones as drivers
    drivers = tuple(selected[:MAX_DRIVERS-1])  # Leave space for at least one other feature

    # All selected features will be used in the model
    columns = selected

    # No interaction terms for this simple approach
    products = ()

    # Weighted score using the first feature's standardized values
    loadings = {drivers[0]: 1.0} if drivers else {}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

